import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Теги","description":"","frontmatter":{},"headers":[],"relativePath":"ru/concepts/tags.md","filePath":"ru/concepts/tags.md","lastUpdated":1784903584000}'),e={name:"ru/concepts/tags.md"};function p(l,s,h,o,d,r){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="теги" tabindex="-1">Теги <a class="header-anchor" href="#теги" aria-label="Permalink to &quot;Теги&quot;">​</a></h1><p>Тег — это категория, которая группирует связанные эндпоинты внутри коллекции. Теги могут присутствовать или отсутствовать — не все коллекции их имеют, и коллекция может содержать любое количество тегов.</p><p>Теги берутся из самого файла OpenAPI/Swagger/Postman. <strong>В YAML-конфиге нет настроек для тегов</strong> — вы не можете создавать, переименовывать или удалять теги в <code>swag2mcp.yaml</code>. Единственный способ изменить теги — отредактировать исходный файл спецификации.</p><h2 id="иерархия" tabindex="-1">Иерархия <a class="header-anchor" href="#иерархия" aria-label="Permalink to &quot;Иерархия&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Спецификация (domain, например &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Коллекция (файл спецификации, например forecast.yml)</span></span>
<span class="line"><span>        └── Тег &quot;weather&quot;</span></span>
<span class="line"><span>              └── GET /forecast</span></span>
<span class="line"><span>              └── GET /forecast/hourly</span></span>
<span class="line"><span>        └── Тег &quot;alerts&quot;</span></span>
<span class="line"><span>              └── GET /alerts</span></span></code></pre></div><h2 id="как-создаются-теги" tabindex="-1">Как создаются теги <a class="header-anchor" href="#как-создаются-теги" aria-label="Permalink to &quot;Как создаются теги&quot;">​</a></h2><p>Теги извлекаются из документа спецификации во время разбора:</p><p><strong>OpenAPI 3.x / Swagger 2.0</strong> — список <code>tags</code> каждой операции становится тегами:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /pet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Найти питомца по ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Добавить нового питомца&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /pet/{petId}/uploadImage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pet_images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Загрузить изображение&quot;</span></span></code></pre></div><p><strong>Postman</strong> — каждая папка верхнего уровня становится тегом. Вложенные папки используют имя последней папки.</p><p>Если у эндпоинта нет тегов, он помещается в тег <code>&quot;default&quot;</code>.</p><h2 id="назначение" tabindex="-1">Назначение <a class="header-anchor" href="#назначение" aria-label="Permalink to &quot;Назначение&quot;">​</a></h2><p>Теги помогают LLM находить группы связанных эндпоинтов. Вместо поиска по всем эндпоинтам коллекции LLM может сначала найти нужный тег, а затем вывести только эндпоинты внутри него.</p><h2 id="mcp-инструменты-для-тегов" tabindex="-1">MCP-инструменты для тегов <a class="header-anchor" href="#mcp-инструменты-для-тегов" aria-label="Permalink to &quot;MCP-инструменты для тегов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Инструмент</th><th>Описание</th></tr></thead><tbody><tr><td><code>tag_by_spec</code></td><td>Все теги во всей спецификации</td></tr><tr><td><code>tag_by_collection</code></td><td>Теги в конкретной коллекции</td></tr><tr><td><code>tag_by_id</code></td><td>Детали тега (название, количество методов)</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Эндпоинты, сгруппированные под тегом</td></tr></tbody></table><h2 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Запрос: &quot;Покажи все теги в коллекции pet&quot;</span></span>
<span class="line"><span>→ tag_by_collection(collectionId: &quot;...&quot;)</span></span>
<span class="line"><span>→ Результат: pets (5 методов), pet_images (1 метод)</span></span></code></pre></div><h2 id="ограничения" tabindex="-1">Ограничения <a class="header-anchor" href="#ограничения" aria-label="Permalink to &quot;Ограничения&quot;">​</a></h2><ul><li>Теги доступны только для чтения с точки зрения конфига. Чтобы добавить, переименовать или удалить теги, отредактируйте исходный файл OpenAPI/Swagger/Postman и выполните <code>swag2mcp update</code>.</li><li>Теги нельзя фильтровать или отключать для отдельных коллекций в YAML-конфиге.</li></ul>`,19)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
